public class GenericStackTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        GenericStack<String> s = new GenericStack<>();
        check("new stack isEmpty()", true, s.isEmpty());
        check("new stack size()", 0, s.size());
        check("pop() on empty returns null", null, s.pop());
        check("peek() on empty returns null", null, s.peek());
        s.push("a");
        s.push("b");
        s.push("c");
        check("size() after three pushes", 3, s.size());
        check("peek() returns the top", "c", s.peek());
        check("peek() does not remove", 3, s.size());
        check("pop() returns the top", "c", s.pop());
        check("pop() again follows LIFO order", "b", s.pop());
        check("size() after two pops", 1, s.size());
        check("isEmpty() with one item left", false, s.isEmpty());
        GenericStack<Integer> nums = new GenericStack<>();
        nums.push(10);
        nums.push(20);
        check("Integer stack pop()", 20, nums.pop());
        check("Integer stack peek() after pop", 10, nums.peek());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
